exercises.solution:
const plano = 45;
const gigasExtras = 3;
const precoDoGiga = 5;

const extras = gigasExtras * precoDoGiga;
const total = plano + extras;
const porDia = total / 30;

console.log('Plano:', plano);
console.log('Gigas extras:', extras);
console.log('Total da conta:', total);
console.log('Por dia:', porDia);

